const std = @import("std");
const sg = @import("root.zig");
const f = @import("fixtures.zig");
const h = @import("test_support.zig");
const wire = @import("wire.zig");

// Catches a borrowed input snapshot or publication without canonical recomputation.
test "decode owns caller snapshot and recomputes canonical bytes" {
    var setup = try sg.Setup.init(std.testing.allocator, 7);
    defer setup.deinit();
    var caller = f.small_wire;
    const token = try setup.beginDecode(&caller);
    @memset(&caller, 0xAA);
    try h.finish(&setup, token, 1);
    try std.testing.expectEqual(@as(u64, 31), (try setup.stats(token)).total_units);
    try std.testing.expectEqual(@as(u16, 177), (try setup.stats(token)).admission_copy_bytes);
    var manifest = try setup.take(token);
    defer manifest.deinit();
    var copied: [16384]u8 = undefined;
    const len = try h.collectWire(&manifest, &copied);
    try std.testing.expectEqualSlices(u8, &f.small_wire, copied[0..len]);
    try std.testing.expectEqualSlices(u8, &f.small_digest, &(try manifest.digest()));
}
// Catches eager parsing, incorrect byte ceiling and malformed input publication.
test "oversize is synchronous but malformed header is polled" {
    var setup = try sg.Setup.init(std.testing.allocator, 8);
    defer setup.deinit();
    const oversized: [16385]u8 = @splat(0);
    try std.testing.expectError(error.InvalidWire, setup.beginDecode(&oversized));
    const token = try setup.beginDecode("NY");
    try std.testing.expectError(error.InvalidWire, h.finish(&setup, token, 1));
    try setup.release(token);
}

fn reject(input: []const u8, expected: sg.Failure) !void {
    var counter = h.Counter.init(std.testing.allocator);
    var setup = try sg.Setup.init(counter.allocator(), 90);
    defer setup.deinit();
    const token = try setup.beginDecode(input);
    try std.testing.expectEqual(sg.Phase.parse_header, (try setup.stats(token)).phase);
    try std.testing.expectError(error.NotReady, setup.take(token));
    for (0..3000) |_| {
        switch (try h.pollChecked(&setup, token, 1, &counter)) {
            .pending => try std.testing.expectError(error.NotReady, setup.take(token)),
            .failed => |cause| {
                try std.testing.expectEqual(expected, cause);
                try std.testing.expectError(error.NotReady, setup.take(token));
                try std.testing.expectEqual(@as(usize, 0), counter.live);
                try setup.release(token);
                return;
            },
            else => return error.InvariantViolation,
        }
    }
    return error.InvariantViolation;
}
// Catches unchecked reads, permissive length/schema handling, or skipped field recomputation.
test "decode rejects every truncation trailing byte and malformed field" {
    for (0..f.small_wire.len) |end| try reject(f.small_wire[0..end], error.InvalidWire);
    var trailing: [178]u8 = undefined;
    @memcpy(trailing[0..177], &f.small_wire);
    trailing[177] = 0;
    try reject(&trailing, error.InvalidWire);
    const Mutation = struct { offset: usize, value: u8, expected: sg.Failure = error.InvalidWire };
    for ([_]Mutation{
        .{ .offset = 0, .value = 0 },
        .{ .offset = 4, .value = 2, .expected = error.UnsupportedWireVersion },
        .{ .offset = 6, .value = 0 },
        .{ .offset = 7, .value = 255 },
        .{ .offset = 8, .value = 0 },
        .{ .offset = 29, .value = 2, .expected = error.InvalidVersion },
        .{ .offset = 31, .value = 1 },
        .{ .offset = 39, .value = 0, .expected = error.CapacityUnsupported },
        .{ .offset = 39, .value = 65, .expected = error.CapacityUnsupported },
        .{ .offset = 41, .value = 0, .expected = error.CapacityUnsupported },
        .{ .offset = 42, .value = 3, .expected = error.CapacityUnsupported },
        .{ .offset = 43, .value = 0, .expected = error.CapacityUnsupported },
        .{ .offset = 43, .value = 17, .expected = error.CapacityUnsupported },
        .{ .offset = 39, .value = 5, .expected = error.InvalidConfig },
        .{ .offset = 43, .value = 5, .expected = error.InvalidConfig },
        .{ .offset = 45, .value = 3, .expected = error.CapacityUnsupported },
        .{ .offset = 45, .value = 33, .expected = error.CapacityUnsupported },
        .{ .offset = 47, .value = 0 },
        .{ .offset = 63, .value = 1 },
        .{ .offset = 51, .value = 120 },
        .{ .offset = 55, .value = 112 },
        .{ .offset = 59, .value = 1 },
        .{ .offset = 79, .value = 0 },
        .{ .offset = 99, .value = 1 },
        .{ .offset = 83, .value = 2 },
        .{ .offset = 87, .value = 1 },
        .{ .offset = 89, .value = 1 },
        .{ .offset = 97, .value = 7 },
        .{ .offset = 159, .value = 0 },
        .{ .offset = 168, .value = 1 },
        .{ .offset = 163, .value = 2 },
        .{ .offset = 167, .value = 1 },
    }) |m| {
        var bytes = f.small_wire;
        bytes[m.offset] = m.value;
        try reject(&bytes, m.expected);
    }
    for ([_]struct { offset: usize, size: usize }{
        .{ .offset = 47, .size = 16 }, .{ .offset = 79, .size = 20 }, .{ .offset = 159, .size = 9 },
    }) |record| {
        var reordered = f.small_wire;
        const start = record.offset;
        const middle = start + record.size;
        const end = middle + record.size;
        @memcpy(reordered[start..middle], f.small_wire[middle..end]);
        @memcpy(reordered[middle..end], f.small_wire[start..middle]);
        try reject(&reordered, error.InvalidWire);
    }
    // A matching hash of tampered coordinates does not establish schema validity.
    var tampered = f.small_wire;
    tampered[51] ^= 1;
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(&tampered, &digest, .{});
    const tampered_digest = comptime f.decodeHex("c4c98ca93ee78118765a348407c87205941e6bc882f10787310980d6684b2f06");
    try std.testing.expectEqualSlices(u8, &tampered_digest, &digest);
    try reject(&tampered, error.InvalidWire);
}

test "decode snapshots survive invalid requests and admission precedence" {
    var counter = h.Counter.init(std.testing.allocator);
    var setup = try sg.Setup.init(counter.allocator(), 91);
    defer setup.deinit();
    const oversized: [16385]u8 = @splat(0);
    try std.testing.expectError(error.InvalidWire, setup.beginDecode(&oversized));
    try std.testing.expectEqual(@as(usize, 0), counter.attempts);
    const token = try setup.beginDecode(&f.small_wire);
    try std.testing.expectEqual(@as(u64, 1), token.id);
    const initial = try setup.stats(token);
    try std.testing.expectEqual(sg.storage.candidateReservation(), initial.requested_bytes);
    try std.testing.expectError(error.Busy, setup.beginDecode(&oversized));
    try std.testing.expectEqual(@as(usize, 2), counter.attempts);
    for (0..31) |_| {
        const before = try setup.stats(token);
        try std.testing.expectError(error.InvalidBudget, setup.poll(token, 4097));
        var foreign = token;
        foreign.owner_namespace += 1;
        try std.testing.expectError(error.StaleJob, setup.poll(foreign, 4097));
        _ = try h.pollChecked(&setup, token, 0, &counter);
        try std.testing.expectEqualDeep(before, try setup.stats(token));
        _ = try h.pollChecked(&setup, token, 1, &counter);
    }
    var manifest = try setup.take(token);
    defer manifest.deinit();
    try std.testing.expectEqualSlices(u8, &f.small_digest, &(try manifest.digest()));
    const next = try setup.beginDecode(&f.small_wire);
    try std.testing.expectEqual(@as(u64, 2), next.id);
    setup.deinit();
    try std.testing.expectError(error.Shutdown, setup.beginDecode(&oversized));
}

test "decode both allocation failures release candidate and consume counters" {
    for (0..2) |failure| {
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = failure });
        var counter = h.Counter.init(failing.allocator());
        var setup = try sg.Setup.init(counter.allocator(), 92);
        defer setup.deinit();
        try std.testing.expectError(error.OutOfMemory, setup.beginDecode(&f.small_wire));
        try std.testing.expectEqual(failure + 1, counter.attempts);
        try std.testing.expectEqual(failure, counter.frees);
        try std.testing.expectEqual(@as(usize, 0), counter.live);
        failing.fail_index = std.math.maxInt(usize);
        const token = try setup.beginDecode(&f.small_wire);
        try std.testing.expectEqual(@as(u64, 2), token.id);
        try std.testing.expectEqual(@as(u64, 2), token.generation);
        try h.finish(&setup, token, 4096);
        try setup.release(token);
        try std.testing.expectEqual(failing.allocations, failing.deallocations);
    }
}

