// Literal inputs prevent a mutually wrong generator and decoder from agreeing.
test "decode canonical fixtures exact charges budgets and mixed zero cadence" {
    const Case = struct { bytes: []const u8, digest: [32]u8, units: u64 };
    for ([_]Case{
        .{ .bytes = &f.small_wire, .digest = f.small_digest, .units = 31 },
        .{ .bytes = &maximum_zero_wire, .digest = f.maximum_zero_digest, .units = 1960 },
        .{ .bytes = &maximum_max_wire, .digest = f.maximum_max_digest, .units = 1960 },
    }) |case| {
        for ([_]u16{ 1, 7, 256, 4096, 0 }) |cadence| {
            var counter = h.Counter.init(std.testing.allocator);
            var setup = try sg.Setup.init(counter.allocator(), 93);
            defer setup.deinit();
            const token = try setup.beginDecode(case.bytes);
            var schedule: u64 = 17;
            var ready = false;
            for (0..3000) |_| {
                const before = try setup.stats(token);
                _ = try h.pollChecked(&setup, token, 0, &counter);
                try std.testing.expectEqualDeep(before, try setup.stats(token));
                schedule = schedule *% 6364136223846793005 +% 1;
                const budget: u16 = if (cadence == 0) @intCast(1 + schedule % 73) else cadence;
                const result = try h.pollChecked(&setup, token, budget, &counter);
                try std.testing.expect((try setup.stats(token)).units_used <= budget);
                switch (result) {
                    .ready => {
                        ready = true;
                        break;
                    },
                    .pending => {},
                    else => return error.InvariantViolation,
                }
            }
            try std.testing.expect(ready);
            try std.testing.expectEqual(case.units, (try setup.stats(token)).total_units);
            var manifest = try setup.take(token);
            defer manifest.deinit();
            var encoded: [16384]u8 = undefined;
            const len = try h.collectWire(&manifest, &encoded);
            try std.testing.expectEqualSlices(u8, case.bytes, encoded[0..len]);
            try std.testing.expectEqualSlices(u8, &case.digest, &(try manifest.digest()));
        }
    }
}

test "decode all 1960 charged cancellation cuts and ready preserve resident" {
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var counter = h.Counter.init(failing.allocator());
    var resident_setup = try sg.Setup.init(counter.allocator(), 1);
    defer resident_setup.deinit();
    const resident_token = try resident_setup.beginDecode(&f.small_wire);
    try h.finish(&resident_setup, resident_token, 4096);
    var resident = try resident_setup.take(resident_token);
    defer resident.deinit();
    for (0..1961) |cut| {
        var setup = try sg.Setup.init(counter.allocator(), cut + 2);
        defer setup.deinit();
        const token = try setup.beginDecode(&maximum_zero_wire);
        for (0..cut) |_| _ = try h.pollChecked(&setup, token, 1, &counter);
        try std.testing.expectEqual(@as(u64, @intCast(cut)), (try setup.stats(token)).total_units);
        try setup.cancel(token);
        try setup.cancel(token);
        try std.testing.expectError(error.NotReady, setup.take(token));
        try std.testing.expectError(error.NotReady, setup.release(token));
        const before = try setup.stats(token);
        const frees = counter.frees;
        _ = try h.pollChecked(&setup, token, 0, &counter);
        try std.testing.expectEqualDeep(before, try setup.stats(token));
        try std.testing.expectEqual(frees, counter.frees);
        try std.testing.expectEqual(.pending, std.meta.activeTag(try h.pollChecked(&setup, token, 1, &counter)));
        try std.testing.expectEqual(frees + 1, counter.frees);
        try setup.cancel(token);
        try std.testing.expectEqual(.canceled, std.meta.activeTag(try h.pollChecked(&setup, token, 1, &counter)));
        try std.testing.expectEqual(frees + 2, counter.frees);
        try std.testing.expectEqual(@as(usize, @sizeOf(sg.storage.Output)), counter.live);
        try setup.release(token);
        try std.testing.expectError(error.StaleJob, setup.poll(token, 1));
        try std.testing.expectEqualSlices(u8, &f.small_digest, &(try resident.digest()));
        var bytes: [177]u8 = undefined;
        _ = try h.collectWire(&resident, &bytes);
        try std.testing.expectEqualSlices(u8, &f.small_wire, &bytes);
        const accounted_peak = counter.peak + 2 * sg.storage.control_envelope_bytes + 2 * sg.storage.output_alignment_pad + sg.storage.scratch_alignment_pad;
        try std.testing.expectEqual(sg.storage.replacementPeakReservation(), accounted_peak);
    }
    resident.deinit();
    try std.testing.expectEqual(@as(usize, 0), counter.live);
    try std.testing.expectEqual(failing.allocations, failing.deallocations);
}

test "decode retained resident survives allocation and schema failures" {
    for ([_]usize{ 2, 3 }) |failure| {
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = failure });
        var counter = h.Counter.init(failing.allocator());
        var setup = try sg.Setup.init(counter.allocator(), 95);
        defer setup.deinit();
        const first = try setup.beginDecode(&f.small_wire);
        try h.finish(&setup, first, 4096);
        var resident = try setup.take(first);
        defer resident.deinit();
        try std.testing.expectError(error.OutOfMemory, setup.beginDecode(&maximum_zero_wire));
        try std.testing.expectEqualSlices(u8, &f.small_digest, &(try resident.digest()));
        try std.testing.expectEqual(@as(usize, @sizeOf(sg.storage.Output)), counter.live);
        failing.fail_index = std.math.maxInt(usize);
        const malformed = try setup.beginDecode("");
        try std.testing.expectError(error.InvalidWire, h.finish(&setup, malformed, 1));
        try setup.release(malformed);
        setup.deinit();
        try std.testing.expectEqualSlices(u8, &f.small_digest, &(try resident.digest()));
        resident.deinit();
        try std.testing.expectEqual(failing.allocations, failing.deallocations);
    }
}

test "decode parsers exact record boundaries signed fields and header precedence" {
    var bytes: [48]u8 = @splat(0);
    for (0..48) |len| {
        if (len != 16) try std.testing.expectError(error.InvalidWire, wire.parseSystem(bytes[0..len]));
        if (len != 20) try std.testing.expectError(error.InvalidWire, wire.parsePlanet(bytes[0..len]));
        if (len != 9) try std.testing.expectError(error.InvalidWire, wire.parseCivilization(bytes[0..len]));
    }
    const signed = comptime f.decodeHex("01000000ffffffff0000008000000000");
    const system = try wire.parseSystem(&signed);
    try std.testing.expectEqual(@as(i32, -1), system.x);
    try std.testing.expectEqual(std.math.minInt(i32), system.y);
    var invalid = f.small_wire;
    invalid[4] = 2;
    invalid[6] = 0;
    invalid[29] = 2;
    invalid[39] = 0;
    try reject(&invalid, error.UnsupportedWireVersion);
    invalid[4] = 1;
    try reject(&invalid, error.InvalidWire);
    invalid[6] = 21;
    try reject(&invalid, error.InvalidVersion);
    invalid[29] = 1;
    try reject(&invalid, error.CapacityUnsupported);
    invalid = f.small_wire;
    invalid[47] = 0;
    const header = try wire.parseHeader(&invalid);
    try std.testing.expectEqualDeep(f.small_config, header.config);
    try std.testing.expectEqual(@as(u16, 47), header.consumed);
    // Length is rejected at config validation before a malformed entity is parsed.
    var setup = try sg.Setup.init(std.testing.allocator, 96);
    defer setup.deinit();
    const token = try setup.beginDecode(invalid[0..176]);
    _ = try setup.poll(token, 1);
    try std.testing.expectEqual(sg.Phase.validate_config, (try setup.stats(token)).phase);
    _ = try setup.poll(token, 1);
    try std.testing.expectEqual(sg.Phase.retire_output, (try setup.stats(token)).phase);
}

// Timing is diagnostic evidence, never a nondeterministic acceptance assertion.
test "decode begin snapshot latency measured separately from poll latency" {
    var admission: [128]i96 = undefined;
    var polling: [1024]i96 = undefined;
    var poll_count: usize = 0;
    var setup = try sg.Setup.init(std.testing.allocator, 97);
    defer setup.deinit();
    for (&admission) |*elapsed| {
        const begin = std.Io.Clock.awake.now(std.testing.io);
        const token = try setup.beginDecode(&maximum_zero_wire);
        elapsed.* = begin.durationTo(std.Io.Clock.awake.now(std.testing.io)).toNanoseconds();
        try std.testing.expectEqual(@as(u16, 11455), (try setup.stats(token)).admission_copy_bytes);
        while (true) {
            const start = std.Io.Clock.awake.now(std.testing.io);
            const progress = try setup.poll(token, 256);
            polling[poll_count] = start.durationTo(std.Io.Clock.awake.now(std.testing.io)).toNanoseconds();
            poll_count += 1;
            if (std.meta.activeTag(progress) == .ready) break;
        }
        try setup.release(token);
    }
    std.mem.sort(i96, &admission, {}, std.sort.asc(i96));
    std.mem.sort(i96, polling[0..poll_count], {}, std.sort.asc(i96));
    std.debug.print("\ndecode begin (allocation + 11455-byte snapshot): n=128 p95_ns={d} max_ns={d}; poll budget256: n={d} p95_ns={d} max_ns={d}\n", .{ admission[121], admission[127], poll_count, polling[(poll_count * 95 + 99) / 100 - 1], polling[poll_count - 1] });
}

test "decode admits full byte ceiling without header work and owns empty input" {
    var counter = h.Counter.init(std.testing.allocator);
    var setup = try sg.Setup.init(counter.allocator(), 98);
    defer setup.deinit();
    const ceiling: [16384]u8 = @splat(0);
    const token = try setup.beginDecode(&ceiling);
    const before = try setup.stats(token);
    try std.testing.expectEqual(@as(u16, 16384), before.admission_copy_bytes);
    try std.testing.expectEqual(@as(u64, 0), before.total_units);
    try std.testing.expectEqual(sg.Phase.parse_header, before.phase);
    _ = try h.pollChecked(&setup, token, 0, &counter);
    try std.testing.expectEqualDeep(before, try setup.stats(token));
    try std.testing.expectEqual(.pending, std.meta.activeTag(try h.pollChecked(&setup, token, 1, &counter)));
    try std.testing.expectEqual(sg.Phase.retire_output, (try setup.stats(token)).phase);
    _ = try h.pollChecked(&setup, token, 2, &counter);
    try std.testing.expectEqual(error.InvalidWire, (try setup.poll(token, 1)).failed);
    try setup.release(token);
    const empty = try setup.beginDecode("");
    try std.testing.expectEqual(@as(u16, 0), (try setup.stats(empty)).admission_copy_bytes);
    try std.testing.expectEqual(@as(u64, 2), empty.id);
    try std.testing.expectError(error.InvalidWire, h.finish(&setup, empty, 1));
    try setup.release(empty);
    try std.testing.expectEqual(@as(usize, 0), counter.live);
}
